<div class="wrap">
  <h1>Pomodoro</h1>
  <p class="hint">25 perc fókuszált munka, majd 5 perc szünet. Nyomd meg a Start gombot, és figyeld a befejezett köröket.</p>

  <div class="card">
    <div class="mode" id="mode">Munka</div>
    <div class="time" id="time">25:00</div>
    <div class="controls">
      <button class="primary" id="startBtn">Start</button>
      <button id="resetBtn">Újraindítás</button>
    </div>
    <div class="stats">
      <div class="stat"><div class="num" id="rounds">0</div><div class="lbl">Befejezett kör</div></div>
      <div class="stat"><div class="num" id="focus">0 p</div><div class="lbl">Össz. fókuszidő</div></div>
    </div>
    <p class="empty" id="empty">Még nincs befejezett kör. Indítsd el az első munkamenetet!</p>
  </div>

  <div class="settings">
    <label for="durSel">Munkamenet hossza</label>
    <select id="durSel">
      <option value="25">25 perc</option>
      <option value="45">45 perc</option>
      <option value="50">50 perc</option>
    </select>
  </div>
  <div class="sr-only" aria-live="polite" id="live"></div>
</div>

<script>
(function () {
  var KEY = 'pomodoro-v1';
  var BREAK = 5 * 60;
  var state = { work: 25 * 60, rounds: 0, focusMin: 0 };
  var mode = 'work';
  var remaining = state.work;
  var running = false;
  var tick = null;

  var timeEl = document.getElementById('time');
  var modeEl = document.getElementById('mode');
  var startBtn = document.getElementById('startBtn');
  var resetBtn = document.getElementById('resetBtn');
  var roundsEl = document.getElementById('rounds');
  var focusEl = document.getElementById('focus');
  var emptyEl = document.getElementById('empty');
  var durSel = document.getElementById('durSel');
  var live = document.getElementById('live');

  function fmt(s) {
    var m = Math.floor(s / 60), sec = s % 60;
    return (m < 10 ? '0' : '') + m + ':' + (sec < 10 ? '0' : '') + sec;
  }

  function render() {
    timeEl.textContent = fmt(remaining);
    timeEl.classList.toggle('break', mode === 'break');
    modeEl.textContent = mode === 'work' ? 'Munka' : 'Szünet';
    startBtn.textContent = running ? 'Szünet' : 'Start';
    roundsEl.textContent = state.rounds;
    focusEl.textContent = state.focusMin + ' p';
    emptyEl.style.display = state.rounds > 0 ? 'none' : 'block';
    document.title = fmt(remaining) + ' · ' + (mode === 'work' ? 'Munka' : 'Szünet');
  }

  function save() {
    if (window.alfy && window.alfy.storage) {
      try { window.alfy.storage.set(KEY, state); } catch (e) {}
    }
  }

  function load() {
    if (window.alfy && window.alfy.storage) {
      try {
        var saved = window.alfy.storage.get(KEY);
        if (saved && typeof saved === 'object') {
          state.work = saved.work || 25 * 60;
          state.rounds = saved.rounds || 0;
          state.focusMin = saved.focusMin || 0;
        }
      } catch (e) {}
    }
    durSel.value = String(state.work / 60);
    remaining = state.work;
  }

  function beep() {
    try {
      var Ctx = window.AudioContext || window.webkitAudioContext;
      if (!Ctx) return;
      var ctx = new Ctx();
      var osc = ctx.createOscillator(), g = ctx.createGain();
      osc.connect(g); g.connect(ctx.destination);
      osc.type = 'sine'; osc.frequency.value = 880;
      g.gain.setValueAtTime(0.0001, ctx.currentTime);
      g.gain.exponentialRampToValueAtTime(0.2, ctx.currentTime + 0.02);
      g.gain.exponentialRampToValueAtTime(0.0001, ctx.currentTime + 0.5);
      osc.start(); osc.stop(ctx.currentTime + 0.55);
    } catch (e) {}
  }

  function switchMode() {
    if (mode === 'work') {
      state.rounds += 1;
      state.focusMin += state.work / 60;
      mode = 'break';
      remaining = BREAK;
      live.textContent = 'Kör befejezve. Szünet kezdődik.';
    } else {
      mode = 'work';
      remaining = state.work;
      live.textContent = 'Szünet vége. Új munkamenet.';
    }
    save();
  }

  function step() {
    remaining -= 1;
    if (remaining <= 0) { beep(); switchMode(); }
    render();
  }

  function start() {
    if (running) return;
    running = true;
    tick = setInterval(step, 1000);
    render();
  }

  function pause() {
    running = false;
    clearInterval(tick);
    render();
  }

  function reset() {
    pause();
    mode = 'work';
    remaining = state.work;
    live.textContent = 'Timer visszaállítva.';
    render();
  }

  startBtn.addEventListener('click', function () { running ? pause() : start(); });
  resetBtn.addEventListener('click', reset);
  durSel.addEventListener('change', function () {
    state.work = parseInt(durSel.value, 10) * 60;
    if (!running) { mode = 'work'; remaining = state.work; }
    save();
    render();
  });

  load();
  render();
})();
</script>
</body>
